size_t nitems2 = ckh->nitems2;
size_t *iter;
size_t *iter2;
size_t i;
size_t n;

if (nitems == 0 && nitems2 == 0) {
    *key = nullptr;
    *data = nullptr;
    return true;
}

*key = nullptr;
*data = nullptr;

if (nitems != 0) {
    hash1 = hash((void *)searchkey);
    iter = &hash1;
    n = nitems;
    iter2 = &n;
} else {
    hash1 = hash2 = 0;
    iter = &hash1;
    iter2 = &hash2;
    n = 0;
}

for (i = 0; i < 2; i++) {
    if (i == 0) {
        if (nitems != 0) {
            *iter = hash((void *)searchkey);
        }
